function animationData(){return state.animation||{duration:5,keys:[],events:[]};}
function commitAnimation(data){try{EmberAnimation.validate(data);state.animation=data;restart();persist();renderAnimation();if($('#dialog').open)$('#dialog').close();}catch(error){const message=$('#animation-error');if(message)message.textContent=error.message;else toast(error.message);}}
function renderAnimation(){const data=animationData();$('#animation-duration').value=data.duration;$('#animation-scrub').max=data.duration;const host=$('#animation-entries');host.replaceChildren();const entries=[...data.keys.map((item,index)=>({item,index,kind:'key'})),...data.events.map((item,index)=>({item,index,kind:'event'}))].sort((a,b)=>a.item.time-b.item.time);if(!entries.length){const hint=document.createElement('p');hint.className='animation-empty';hint.textContent='No animation yet. Try changing color at 1 second, then adding sparks at 2 seconds.';host.append(hint);}for(const entry of entries){const row=document.createElement('div');row.className='animation-entry';const edit=document.createElement('button');const item=entry.item;edit.textContent=item.time.toFixed(2)+' s · '+(entry.kind==='key'?EmberAnimation.properties[item.property][0]+' → '+(typeof item.value==='boolean'?(item.value?'On':'Off'):item.value)+(item.transition==='linear'?' · gradual':''):item.type==='burst'?'Add '+item.count+' particles':'Clear existing particles');edit.onclick=()=>entry.kind==='key'?editAnimationKey(entry.index):editAnimationEvent(entry.index);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove animation at '+item.time+' seconds');remove.onclick=()=>{const data=structuredClone(animationData());data[entry.kind==='key'?'keys':'events'].splice(entry.index,1);commitAnimation(data);};row.append(edit,remove);host.append(row);}updateAnimationPlayhead();}
function animationForm(title){dialog('<div class="eyebrow">LAYER ANIMATION</div><h2>'+title+'</h2><div id="animation-form"></div><p id="animation-error" role="alert"></p><button id="save-animation" class="primary">Save animation step</button>');return $('#animation-form');}
function field(host,labelText,element){const label=document.createElement('label');label.textContent=labelText;label.append(element);host.append(label);return element;}
function numberInput(value,min,max,step,label){const input=document.createElement('input');input.type='number';input.min=min;input.max=max;input.step=step;input.value=value;input.setAttribute('aria-label',label);return input;}
function selectInput(options,value,label){const select=document.createElement('select');select.setAttribute('aria-label',label);for(const [id,name] of options){const option=document.createElement('option');option.value=id;option.textContent=name;select.append(option);}select.value=value;return select;}
function editAnimationKey(index){const data=structuredClone(animationData()),key=index===undefined?{time:Math.min(1,data.duration),property:'color',value:state.color,transition:'hold'}:data.keys[index];const form=animationForm('Change a particle property.');const time=field(form,'At time (seconds)',numberInput(key.time,0,data.duration,.1,'Keyframe time'));const property=field(form,'Property',selectInput(Object.entries(EmberAnimation.properties).map(([id,def])=>[id,def[0]]),key.property,'Animated property'));const hint=document.createElement('p');hint.className='animation-intro';form.append(hint);const holder=document.createElement('div');form.append(holder);let value;const transition=field(form,'How it changes',selectInput([['hold','At this time — switch instantly'],['linear','Gradually — blend from the previous value']],key.transition,'Animation transition'));function renderValue(){holder.replaceChildren();hint.textContent=['radiusVariation','directionRandom','spriteRotationRandom'].includes(property.value)?'This changes the random variation assigned to newly created particles.':property.value.startsWith('emitScale')?'This stretches the starting region. In ring orbit, X/Y stretch also reshapes existing orbits.':['velocityYaw','velocityPitch'].includes(property.value)?'Velocity angles apply in Aim the velocity mode and affect new particles.':property.value==='ringSpin'?'Ring spin applies in Spin around a ring mode and changes the rotation of existing particles.':property.value==='emission'?'Off stops new particles. Existing particles remain until they expire or a Clear event removes them.':property.value==='amount'?'Sets particles per second for Continuous flow. Use a burst event to add a fixed number of particles.':['velocityYaw','velocityPitch','speed','spread','life','positionX','positionY','positionZ'].includes(property.value)?'This changes newly created particles. Existing particles keep their original starting settings.':'This changes particles already visible as well as new particles.';const def=EmberAnimation.properties[property.value],current=property.value===key.property?key.value:EmberAnimation.evaluate(state,+time.value)[property.value];if(def[1]==='boolean')value=selectInput([['true','On — new particles appear'],['false','Off — stop creating new particles']],String(current),'Animated value');else if(def[1]==='color'){value=document.createElement('input');value.type='color';value.value=current;value.setAttribute('aria-label','Animated value');}else value=numberInput(current,def[1],def[2],.1,'Animated value');field(holder,'New value',value);transition.disabled=def[1]==='boolean';if(transition.disabled)transition.value='hold';}property.onchange=renderValue;renderValue();$('#save-animation').onclick=()=>{const def=EmberAnimation.properties[property.value];const next={time:time.valueAsNumber,property:property.value,value:def[1]==='color'?value.value:def[1]==='boolean'?value.value==='true':value.valueAsNumber,transition:transition.value};if(index===undefined)data.keys.push(next);else data.keys[index]=next;commitAnimation(data);};}
function editAnimationEvent(index){const data=structuredClone(animationData()),event=index===undefined?{time:Math.min(2,data.duration),type:'burst',count:100}:data.events[index];const form=animationForm('Add or remove particles.');const time=field(form,'At time (seconds)',numberInput(event.time,0,data.duration,.1,'Particle event time'));const type=field(form,'Action',selectInput([['burst','Add a burst of particles'],['clear','Clear all existing particles in this layer']],event.type,'Particle event action'));const count=field(form,'Number of new particles',numberInput(event.count||100,1,2000,1,'Burst particle count'));const keep=document.createElement('input');keep.type='checkbox';keep.checked=event.keepAnimation!==false;keep.setAttribute('aria-label','Keep animated properties');field(form,'Keep animated properties',keep);const hint=document.createElement('p');hint.className='animation-intro';form.append(hint);type.onchange=()=>{count.closest('label').hidden=type.value==='clear';keep.closest('label').hidden=type.value==='clear';hint.textContent=type.value==='clear'?'Removes particles already in this layer. Add an Emit new particles → Off step at the same time to keep it empty.':'Creates particles once at this time, even if Emit new particles is Off. Keep animated properties follows the layer timeline. Turn it off to use base property settings for these particles; lifetime curves still apply.';};type.onchange();$('#save-animation').onclick=()=>{const next={time:time.valueAsNumber,type:type.value};if(next.type==='burst'){next.count=count.valueAsNumber;next.keepAnimation=keep.checked;}if(index===undefined)data.events.push(next);else data.events[index]=next;commitAnimation(data);};}
$('#add-keyframe').onclick=()=>editAnimationKey();$('#add-animation-event').onclick=()=>editAnimationEvent();$('#animation-help').onclick=()=>openDocumentation('animation');$('#animation-duration').onchange=e=>{const data=structuredClone(animationData());data.duration=e.target.valueAsNumber;commitAnimation(data);renderAnimation();};
window.updateAnimationPlayhead=()=>{const time=layers[activeLayer]?.time||0;$('#time').textContent=time.toFixed(2)+' s';$('#animation-scrub').value=Math.min(time,animationData().duration);$('.loop').textContent=state.animation?.keys.length||state.animation?.events.length||state.eventRules?.length?'↺ Restart to replay':state.mode==='burst'?'↻ Burst loop':'Live preview';};
$('#animation-scrub').oninput=e=>{const target=+e.target.value;restart();for(let time=0;time<target;time+=1/60){const dt=Math.min(1/60,target-time);for(const layer of layers)if(layer.enabled)EmberAnimation.update(layer,dt,true,Math.random,false);}playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play preview');updateAnimationPlayhead();};
const animationSync=sync;sync=()=>{animationSync();renderAnimation();};renderAnimation();

$('#open-animation').onclick=()=>{$('#animation-panel').open=true;$('#animation-panel').scrollIntoView({behavior:'smooth',block:'start'});$('#add-keyframe').focus({preventScroll:true});};

$('#restart').onclick=()=>{restart();playing=true;$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause preview');updateAnimationPlayhead();};
